__node_read_remote_index() {
    local -n __nrri_out="$1"
    __nrri_out="$(nvm ls-remote --no-colors 2>/dev/null)"
    [[ "$__nrri_out" =~ v[0-9]+\.[0-9]+\.[0-9]+ ]]
}

